import { forwardRef, type LabelHTMLAttributes } from "react";

import { cn } from "@/lib/cn";

/** Props accepted by Label. */
export type LabelProps = {
  /** Adds a quiet "Optional" readout after the text. */
  optional?: boolean;
  required?: boolean;
} & LabelHTMLAttributes<HTMLLabelElement>;

/** A label primitive that associates caller-provided text with a form control. */
export const Label = forwardRef<HTMLLabelElement, LabelProps>(function Label(
  { children, className, optional, required, ...props },
  ref,
) {
  return (
    <label
      {...props}
      className={cn(
        "label caps-label cursor-pointer justify-start gap-sm text-sm font-semibold text-base-content",
        className,
      )}
      ref={ref}
    >
      {children}
      {required ? (
        <span aria-hidden="true" className="text-error">
          *
        </span>
      ) : null}
      {optional && !required ? (
        <span className="caps-label-optional">Optional</span>
      ) : null}
    </label>
  );
});

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
